// ─── SCREEN 4: ANALYSIS ──────────────────────────────────────────────────────
function AnalysisScreen({ progress, setProgress, complete, setComplete, email, setEmail, emailSent, setEmailSent, onNext }) {
  const raf = useRef(null);
  const started = useRef(false);

  useEffect(() => {
    if (started.current) return;
    started.current = true;
    let current = 0;
    const steps = [
      { target: 35, speed: 200 },
      { target: 38, speed: 800 },
      { target: 72, speed: 120 },
      { target: 75, speed: 600 },
      { target: 100, speed: 80 },
    ];
    let stepIdx = 0;
    const tick = () => {
      if (stepIdx >= steps.length) return;
      const { target, speed } = steps[stepIdx];
      if (current < target) {
        current++;
        setProgress(current);
        raf.current = setTimeout(tick, speed + Math.random()*50);
      } else {
        stepIdx++;
        raf.current = setTimeout(tick, 300);
      }
    };
    tick();
    return () => clearTimeout(raf.current);
  }, []);

  useEffect(() => {
    if (progress >= 100 && !complete) {
      setTimeout(() => setComplete(true), 500);
    }
  }, [progress, complete]);

  const stageStatus = (s) => {
    if (progress < 35) return s === 0 ? 'active' : 'wait';
    if (progress < 75) return s === 0 ? 'done' : s === 1 ? 'active' : 'wait';
    if (progress < 100) return s < 2 ? 'done' : 'active';
    return 'done';
  };

  const stages = ['Анализ вокальных характеристик','Распознавание микромимики','Сопоставление с моделью ИКИГАЙ'];
  const r = 70, circ = 2 * Math.PI * r;
  const offset = circ - (progress / 100) * circ;

  return (
    <div className="scroll" style={{ height:'calc(100vh - 57px)', overflowY:'auto', padding:'24px' }}>
      <div style={{ textAlign:'center', marginBottom:28 }}>
        <h1 className="ub" style={{ fontSize:20, fontWeight:900, marginBottom:8 }}>
          {complete ? '✅ Анализ завершён' : '✨ Идёт магия ИИ'}
        </h1>
        <p className="ml" style={{ fontSize:13, color:'rgba(255,255,255,0.5)' }}>
          {complete ? 'Твой отчёт готов!' : 'Алгоритмы изучают твой психотип по голосу и чертам лица'}
        </p>
      </div>

      {/* Progress ring */}
      {!complete && (
        <div style={{ display:'flex', justifyContent:'center', marginBottom:28 }}>
          <div style={{ position:'relative', width:180, height:180 }}>
            <svg width="180" height="180" style={{ transform:'rotate(-90deg)' }}>
              <circle cx="90" cy="90" r={r} fill="none" stroke="rgba(255,255,255,0.05)" strokeWidth="10" />
              <circle cx="90" cy="90" r={r} fill="none" stroke="rgba(255,255,255,0.03)" strokeWidth="20" strokeDasharray={circ} strokeDashoffset={0} />
              <circle cx="90" cy="90" r={r} fill="none" stroke="url(#rg)" strokeWidth="10" strokeLinecap="round"
                strokeDasharray={circ} strokeDashoffset={offset} style={{ transition:'stroke-dashoffset .15s ease' }} />
              <defs>
                <linearGradient id="rg" x1="0%" y1="0%" x2="100%" y2="0%">
                  <stop offset="0%" stopColor="#00D4FF" />
                  <stop offset="100%" stopColor="#9B5DE5" />
                </linearGradient>
              </defs>
            </svg>
            <div style={{ position:'absolute', inset:0, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center' }}>
              <div className="ub cyan" style={{ fontSize:36, fontWeight:900, lineHeight:1 }}>{progress}%</div>
              <div className="ml" style={{ fontSize:11, color:'rgba(255,255,255,0.5)', marginTop:4 }}>обработка</div>
            </div>
          </div>
        </div>
      )}

      {/* Stages */}
      <div className="glass" style={{ padding:'20px', marginBottom:20 }}>
        {stages.map((s, i) => {
          const st = stageStatus(i);
          return (
            <div key={i} style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom: i<stages.length-1 ? 14 : 0 }}>
              <div style={{ display:'flex', alignItems:'center', gap:10 }}>
                <div style={{ width:8, height:8, borderRadius:'50%', background: st==='done' ? '#00FF88' : st==='active' ? '#00D4FF' : 'rgba(255,255,255,0.2)', boxShadow: st==='active' ? '0 0 8px #00D4FF' : 'none', animation: st==='active' ? 'pulse 1.5s infinite' : 'none' }} />
                <span className="ml" style={{ fontSize:13, color: st==='wait' ? 'rgba(255,255,255,0.3)' : '#fff' }}>{s}</span>
              </div>
              <span className={cx('badge-'+st)}>{st==='wait'?'В очереди':st==='active'?'В процессе':'Готово'}</span>
            </div>
          );
        })}
      </div>

      {/* Email gate */}
      {complete && !emailSent && (
        <div className="glass neon-border fade-up" style={{ padding:'20px', marginBottom:16 }}>
          <div className="ub" style={{ fontSize:13, fontWeight:700, marginBottom:6 }}>📧 Куда отправить ваш отчёт?</div>
          <p className="ml" style={{ fontSize:12, color:'rgba(255,255,255,0.5)', marginBottom:16 }}>
            Получи отчёт на почту — он всегда будет у тебя
          </p>
          <input className="input" placeholder="твой@email.com" value={email} onChange={e => setEmail(e.target.value)} style={{ marginBottom:12 }} />
          <button className="btn" onClick={() => { if(email) setEmailSent(true); }}>
            Отправить бесплатный отчёт
          </button>
        </div>
      )}

      {emailSent && (
        <div className="glass fade-up" style={{ padding:'20px', marginBottom:16, border:'1px solid rgba(0,255,136,0.3)' }}>
          <div style={{ textAlign:'center', marginBottom:12 }}>
            <div style={{ fontSize:32, marginBottom:8 }}>✅</div>
            <div className="ub" style={{ fontSize:13 }}>Бесплатный отчёт успешно отправлен!</div>
            <div className="ml" style={{ fontSize:12, color:'rgba(255,255,255,0.5)', marginTop:4 }}>Проверьте почту {email}</div>
          </div>
          <button className="btn" onClick={onNext}>Посмотреть результат →</button>
        </div>
      )}

      {complete && !emailSent && false && (
        <button className="btn-ghost" onClick={onNext} style={{ width:'100%' }}>Пропустить и смотреть результат</button>
      )}
    </div>
  );
}

